where not exists (
  select 1 from public.creator_portfolio p where p.creator_id = c.id and p.url = v.url
);

-- ── Open campaigns ─────────────────────────────────────────────────────────
insert into public.campaigns (brand_name, title, category, content_type, platform, spots_total, spots_filled, rate_label, brief_text, emoji, accent_bg, status, published_at)
select * from (values
  ('LuminaSkin', 'Skincare UGC — 30sec testimonial video', 'Beauty', 'Testimonial', 'TikTok + Meta', 8, 4, '$80–120/video', 'LuminaSkin is looking for beauty creators to produce testimonial content for TikTok + Meta. Rate: $80–120/video.', '🧴', '#F2ECEE', 'active', now()),
  ('PowerFit Pro', 'Fitness supplement — unboxing + review', 'Fitness', 'Unboxing', 'Instagram Reels', 8, 6, '$95–150/video', 'PowerFit Pro is looking for fitness creators to produce unboxing content for Instagram Reels. Rate: $95–150/video.', '🏋️', '#EEF2EE', 'active', now()),
  ('NoodleCo', 'Recipe creator — authentic cooking content', 'Food', 'UGC Video', 'TikTok', 8, 2, '$65–100/video', 'NoodleCo is looking for food creators to produce ugc video content for TikTok. Rate: $65–100/video.', '🍜', '#F2F0EC', 'active', now()),
  ('Tempo Studio', 'Activewear — lifestyle content batch', 'Fashion', 'Lifestyle', 'Instagram + TikTok', 8, 5, '$100–180/video', 'Tempo Studio is looking for fashion creators to produce lifestyle content for Instagram + TikTok. Rate: $100–180/video.', '👗', '#F0ECF2', 'active', now()),
  ('PawsNatural', 'Pet food UGC — pet and owner testimonial', 'Pet', 'Testimonial', 'TikTok', 8, 0, '$70–120/video', 'PawsNatural is looking for pet creators to produce testimonial content for TikTok. Rate: $70–120/video.', '🐾', '#F0F2EC', 'active', now()),
  ('Stackr App', 'Productivity app review — talking head', 'Tech', 'Review', 'YouTube Shorts + Meta', 8, 3, '$90–140/video', 'Stackr App is looking for tech creators to produce review content for YouTube Shorts + Meta. Rate: $90–140/video.', '💻', '#ECF0F2', 'active', now())
) as v(brand_name, title, category, content_type, platform, spots_total, spots_filled, rate_label, brief_text, emoji, accent_bg, status, published_at)
where not exists (select 1 from public.campaigns c where c.title = v.title);

